package com.rezoxnemesis.videostudio;
import android.graphics.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SketchContourPaintTest {
 static JSONObject fixture()throws Exception{
  JSONObject d=SketchDocument.create(new JSONObject().put("sketchId","fill_study").put("width",256).put("height",256).put("frameCount",1));
  JSONObject path=SketchEditOps.completeObject(new JSONObject().put("id","authored_outline").put("kind","path").put("fill",false).put("commands",new JSONArray("[['M',.1,.1],['L',.9,.1],['L',.9,.9],['L',.1,.9],['Z'],['M',.4,.4],['L',.6,.4],['L',.6,.6],['L',.4,.6],['Z']]")));
  SketchEditOps.apply(d,new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",path));return d;
 }
 @Test public void closedOwnedContourRetainsHoleAndSourceAndBindsEveryCoordinate()throws Exception{
  JSONObject d=fixture();String before=SketchDocument.canonical(d);JSONObject pin=SketchContourPaint.pin(d,"authored_outline");Path path=SketchContourPaint.path(pin);Bitmap b=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);try{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.WHITE);new Canvas(b).drawPath(path,p);assertEquals(Color.WHITE,b.getPixel(64,64));assertEquals(0,b.getPixel(128,128));assertEquals(0,b.getPixel(1,1));}finally{b.recycle();}assertEquals(before,SketchDocument.canonical(d));
  String sha=pin.getString("sha256");SketchDocument.object(d,"authored_outline").getJSONArray("commands").getJSONArray(1).put(1,.85);assertNotEquals(sha,SketchContourPaint.pin(d,"authored_outline").getString("sha256"));
 }
 @Test public void actualFillRetainsHolesSurvivesUndoReplayAndArchiveWithoutReferencePixels()throws Exception{
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{worker.submit(()->{try{
   android.content.Context c=RuntimeEnvironment.getApplication();String id="contour_"+java.util.UUID.randomUUID();SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","new").put("width",256).put("height",256).put("frameCount",1));JSONObject contour=SketchDocument.object(fixture(),"authored_outline");
   SketchEditOps.execute(c,"sketch_edit",new JSONObject().put("sketchId",id).put("expectedRevision",1).put("operationId","outline").put("operations",new JSONArray().put(new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",contour)).put(new JSONObject().put("type","add_paint_cel").put("layerId","layer_1").put("objectId","base"))));
   JSONObject before;try(SketchProjectStore store=new SketchProjectStore(c)){before=store.get(id);}JSONObject pin=SketchContourPaint.pin(before,"authored_outline"),fill=new JSONObject().put("type","paint_fill").put("objectId","base").put("strokeId","owned_fill").put("contourObjectId","authored_outline").put("expectedContourSha256",pin.getString("sha256")).put("color","#FFFFFFFF");JSONObject args=new JSONObject().put("sketchId",id).put("expectedRevision",2).put("operationId","fill").put("operations",new JSONArray().put(fill));JSONObject receipt=SketchEditOps.execute(c,"sketch_edit",args);assertEquals(SketchDocument.canonical(receipt),SketchDocument.canonical(SketchEditOps.execute(c,"sketch_edit",args)));
   JSONObject filled,event=null;try(SketchProjectStore store=new SketchProjectStore(c)){filled=store.get(id);JSONArray events=store.liveEvents(id,0,32).getJSONArray("events");for(int i=0;i<events.length();i++){JSONArray ops=events.getJSONObject(i).getJSONArray("operations");for(int j=0;j<ops.length();j++)if("paint_fill".equals(ops.getJSONObject(j).getString("type")))event=ops.getJSONObject(j);}}
   assertEquals("base",filled.getJSONArray("layers").getJSONObject(0).getJSONArray("objects").getJSONObject(0).getString("id"));assertEquals(pin.getString("sha256"),SketchContourPaint.pin(filled,"authored_outline").getString("sha256"));assertNotNull(event);
   try(SketchPaintStore paint=new SketchPaintStore(c,id)){JSONObject d=SketchDocument.object(filled,"base").getJSONObject("paint");assertEquals("#FFFFFFFF",paint.sample(d,.2,.2));assertEquals("#00000000",paint.sample(d,.5,.5));assertEquals("#00000000",paint.sample(d,.01,.01));paint.verify(d);assertEquals("paint_fill",paint.journal(d,0,8).getJSONObject(0).getJSONObject("request").getString("type"));Bitmap prefix=paint.renderPrefix(event,.5,256,null);try{assertEquals(0,prefix.getPixel(64,64));}finally{prefix.recycle();}}
   SketchEditOps.execute(c,"sketch_undo",new JSONObject().put("sketchId",id).put("expectedRevision",3).put("operationId","undo"));try(SketchProjectStore store=new SketchProjectStore(c)){assertEquals("authored_outline",store.get(id).getJSONArray("layers").getJSONObject(0).getJSONArray("objects").getJSONObject(0).getString("id"));}
   SketchEditOps.execute(c,"sketch_redo",new JSONObject().put("sketchId",id).put("expectedRevision",4).put("operationId","redo"));SketchPaintArchive.Prepared archive=SketchPaintArchive.prepare(c,new JSONObject().put("sketchId",id).put("expectedRevision",5).put("operationId","archive"));JSONObject restored=SketchPaintArchive.restoreFile(c,archive.file,SketchProjectStore.fileHash(archive.file),"restore","Restored contour study");try(SketchProjectStore store=new SketchProjectStore(c);SketchPaintStore paint=new SketchPaintStore(c,restored.getString("sketchId"))){JSONObject d=store.get(restored.getString("sketchId"));paint.verify(SketchDocument.object(d,"base").getJSONObject("paint"));assertEquals("#FFFFFFFF",paint.sample(SketchDocument.object(d,"base").getJSONObject("paint"),.2,.2));assertEquals("#00000000",paint.sample(SketchDocument.object(d,"base").getJSONObject("paint"),.5,.5));}
   return null;
  }catch(Exception failure){throw new RuntimeException(failure);}}).get(60,java.util.concurrent.TimeUnit.SECONDS);}finally{worker.shutdownNow();}
 }
 @Test public void curvedFillAcrossTilesMatchesNativeWholeCanvasAndRetainsOutsidePaint()throws Exception{
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{worker.submit(()->{try{
   android.content.Context c=RuntimeEnvironment.getApplication();String id="curve_"+java.util.UUID.randomUUID();JSONObject d=SketchDocument.create(new JSONObject().put("sketchId",id).put("width",512).put("height",768).put("frameCount",1));
   try(SketchPaintStore assets=new SketchPaintStore(c,id)){
    JSONObject base=SketchEditOps.completeObject(new JSONObject().put("id","base").put("kind","paint").put("bounds",new JSONObject("{x:0,y:0,width:1,height:1}")).put("paint",assets.empty(512,768)));SketchEditOps.apply(d,new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",base));
    JSONObject outline=SketchEditOps.completeObject(new JSONObject().put("id","curve").put("kind","path").put("fill",false).put("commands",new JSONArray("[['M',.1,.1],['C',.4,.02,.9,.3,.9,.55],['L',.55,.45],['C',.6,.7,.7,.95,.3,.9],['L',.1,.7],['Z'],['M',.3,.3],['C',.3,.5,.5,.5,.5,.3],['Z']]")));SketchEditOps.apply(d,new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",outline));
    JSONObject brush=new JSONObject().put("mode","paint").put("color","#FF536B82").put("sizePx",90).put("hardness",1).put("flow",1).put("pressure",false);JSONObject mark=new JSONObject().put("type","paint_stroke").put("objectId","base").put("strokeId","prior_pixels").put("points",new JSONArray("[[.02,.5,1],[.98,.5,1]]")).put("brush",brush);SketchPaintOps.applyPreparedStroke(d,assets.prepare(d,mark).visualOperation);
    Bitmap expected=assets.render(SketchDocument.object(d,"base").getJSONObject("paint"),768,null);try{JSONObject pin=SketchContourPaint.pin(d,"curve"),request=new JSONObject().put("type","paint_fill").put("objectId","base").put("strokeId","curved_area").put("contourObjectId","curve").put("expectedContourSha256",pin.getString("sha256")).put("color","#806050A0");Paint color=new Paint(Paint.ANTI_ALIAS_FLAG);color.setStyle(Paint.Style.FILL);color.setColor(0x806050A0);new Canvas(expected).drawPath(SketchContourPaint.path(pin),color);SketchPaintOps.applyPreparedStroke(d,assets.prepareFill(d,request).visualOperation);Bitmap actual=assets.render(SketchDocument.object(d,"base").getJSONObject("paint"),768,null);try{int[] wanted=new int[512*768],got=new int[wanted.length];expected.getPixels(wanted,0,512,0,0,512,768);actual.getPixels(got,0,512,0,0,512,768);String diagnostic=System.getenv("VIDEOSTUDIO_CONTOUR_DIAGNOSTIC");if(diagnostic!=null){java.io.File root=new java.io.File(diagnostic);root.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(root,"whole-canvas.png"))){expected.compress(Bitmap.CompressFormat.PNG,100,out);}try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(root,"stored-tiles.png"))){actual.compress(Bitmap.CompressFormat.PNG,100,out);}Bitmap tile=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);try{new Canvas(tile).drawPath(SketchContourPaint.path(pin),color);java.io.ByteArrayOutputStream png=new java.io.ByteArrayOutputStream();tile.compress(Bitmap.CompressFormat.PNG,100,png);Bitmap decoded=BitmapFactory.decodeByteArray(png.toByteArray(),0,png.size());try{System.out.println("CONTOUR_RGBA_PROBE full="+Integer.toHexString(expected.getPixel(98,66))+" tile="+Integer.toHexString(tile.getPixel(98,66))+" decoded="+Integer.toHexString(decoded.getPixel(98,66))+" stored="+Integer.toHexString(actual.getPixel(98,66)));}finally{decoded.recycle();}}finally{tile.recycle();}}
    assertArrayEquals("Native tile fills must preserve the same curve alpha, holes and retained RGBA as a whole-canvas draw",wanted,got);}finally{actual.recycle();}
     String unchanged=SketchDocument.canonical(d);Thread.currentThread().interrupt();try{assertThrows(InterruptedException.class,()->assets.prepareFill(d,request));}finally{Thread.interrupted();}assertEquals(unchanged,SketchDocument.canonical(d));
    }finally{expected.recycle();}
   }return null;
  }catch(Exception failure){throw new RuntimeException(failure);}}).get(60,java.util.concurrent.TimeUnit.SECONDS);}finally{worker.shutdownNow();}
 }
 @Test public void boundsAndStrictFillArgumentsRejectBeforePainting()throws Exception{
  JSONObject d=fixture();d.put("width",2048).put("height",2048);assertThrows(IllegalArgumentException.class,()->SketchContourPaint.pin(d,"authored_outline"));
  JSONObject request=new JSONObject().put("type","paint_fill").put("objectId","base").put("strokeId","fill").put("contourObjectId","path").put("expectedContourSha256","a".repeat(64)).put("color","#FFFFFFFF");for(Object invalid:new Object[]{1,JSONObject.NULL,"#00FFFFFF"}){request.put("color",invalid);assertThrows(IllegalArgumentException.class,()->SketchContourPaint.request(request));}request.put("color","#FFFFFFFF").put("beforePaint",new JSONObject());assertThrows(IllegalArgumentException.class,()->SketchContourPaint.request(request));
 }
 @Test public void openTransformedAnimatedAndCopiedInputsAreRejected()throws Exception{
  JSONObject d=fixture();JSONObject outline=SketchDocument.object(d,"authored_outline");outline.getJSONArray("commands").remove(outline.getJSONArray("commands").length()-1);JSONObject opened=d;assertThrows(IllegalArgumentException.class,()->SketchContourPaint.pin(opened,"authored_outline"));
  d=fixture();outline=SketchDocument.object(d,"authored_outline");outline.getJSONObject("transform").put("rotation",1);JSONObject transformed=d;assertThrows(IllegalArgumentException.class,()->SketchContourPaint.pin(transformed,"authored_outline"));
  JSONObject tampered=SketchContourPaint.pin(fixture(),"authored_outline");tampered.getJSONObject("object").getJSONArray("commands").getJSONArray(1).put(1,.8);assertThrows(IllegalArgumentException.class,()->SketchContourPaint.path(tampered));
 }
}
